export const transcribeAudio = async (audioInput?: AudioInput, options?: Parameters<typeof customFetch>[1]): Promise<LegacyPayload> => {
    const formData = new FormData();
if(audioInput?.audio !== undefined) {
 formData.append(`audio`, audioInput.audio);
 }
if(audioInput?.duration !== undefined) {
 formData.append(`duration`, audioInput.duration);
 }

  return customFetch<LegacyPayload>(getTranscribeAudioUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





